package com.team2.wellness.engagement.ai.api;
import com.team2.wellness.engagement.ai.application.AiGenerationService; import com.team2.wellness.engagement.ai.domain.AiGenerationJob; import com.team2.wellness.engagement.port.out.CurrentUserPort; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.NotNull; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/engagement/ai-generations") public class AiGenerationController { private final CurrentUserPort user; private final AiGenerationService ai; public AiGenerationController(CurrentUserPort user,AiGenerationService ai){this.user=user;this.ai=ai;} @PostMapping @ResponseStatus(HttpStatus.ACCEPTED) AiGenerationService.JobView request(@Valid @RequestBody Request request){return new AiGenerationService.JobView(ai.request(user.currentUserId(),request.targetUserId(),request.occurrenceId(),request.clientRequestId()));} @GetMapping("/{jobId}") AiGenerationService.JobView get(@PathVariable UUID jobId){return ai.get(user.currentUserId(),jobId).map(AiGenerationService.JobView::new).orElseThrow(()->new com.team2.wellness.common.api.ApiException(HttpStatus.NOT_FOUND,"AI_JOB_NOT_FOUND","AI job not found"));} record Request(@NotNull UUID targetUserId,@NotNull UUID occurrenceId,@NotBlank String clientRequestId){} }
